// Sort Emails: sorts every email into a category, matches invoices to rows already
// on the bills tab, works out the Review flags, and outputs three kinds of item:
//   kind 'add'    -> a new bill row          (Add Bill Rows)
//   kind 'update' -> Review/Updates changes   (Update Bill Rows)
//   kind 'log'    -> one row per email        (Log Emails, Mark Done)
// Reads: Get Test Emails (emails), Read PDFs (PDF text), Get Bill Rows (the sheet).
// Settings: Mode = Run Once for All Items, Language = JavaScript.

// ---------- Rules ----------
const CAMPUSES = [
  { name: 'Northview High', pattern: /\bnorthview\b/i },
  { name: 'Eastlake Middle', pattern: /\beastlake\b/i },
  { name: 'Westside Elementary', pattern: /\bwestside\b/i },
];
const SCHOOL_SIGNOFF = /inspireawesomeness academy|northview high|eastlake middle|westside elementary/i;

// Categories, checked in this order; the first match wins.
const SUSPICIOUS = /\b(venmo|zelle|cash ?app|gift ?cards?)\b|\bbank(ing)? (details|information|info)\b|\bchanged (our )?banks?\b|\bnew (bank )?account\b|\brouting number\b/i;
const REIMBURSEMENT = /\breimburs/i;
const STATEMENT_CREDIT = /\bcredit memo\b|\bmonthly statement\b|\baccount statement\b/i;
const RECEIPT = /(?<!on )\breceipt\b|\bpayment received\b|\breceived your payment\b|\bpayment confirmation\b|\bthank you for your payment\b|\bpaid in full\b|\bdeposit received\b|\breceived your deposit\b/i;
const MARKETING = /\bnewsletter\b|\bunsubscribe\b|\bearly bird\b|\bregister now\b|\bwebinar\b/i;
const INVOICE_WORDS = /\binvoice\b|\bbill\b|\bamount due\b|\bbalance due\b|\btotal due\b|\bpayment due\b|\bdue date\b/i;
const BILL_CATEGORIES = ['Possible fraud', 'Invoice'];

// Network-wide wording for the Campus column. (Naming all three campuses also counts as Network.)
const NETWORK = /\b(whole|entire) network\b|\ball (three |3 )?(of our )?campuses\b|\bnetwork[- ]wide\b/i;

// Review flags
const STICKY_FLAGS = ['Possible fraud', 'Changed after approval'];
const DECIDED = ['approved', 'paid', 'denied'];
const APPROVED = ['approved', 'paid'];
const TODAY = DateTime.now().setZone('America/New_York').startOf('day');

// ---------- Helpers ----------
const MONEY = '\\$\\s?(\\d[\\d,]*(?:\\.\\d{2})?)';
const AMOUNT_LABELS = ['amount now due', 'amount due', 'amount owed', 'balance due', 'total due', 'invoice total', 'total'];
const DATE = '(\\d{1,2}\\/\\d{1,2}\\/\\d{4}|\\d{4}-\\d{2}-\\d{2}|[A-Za-z]{3,9}\\.?\\s+\\d{1,2},?\\s+\\d{4})';
const DUE_DATE = new RegExp('\\bdue\\b(?:\\s+date)?(?:\\s+(?:is|was|by|on))?\\s*[:\\-]?\\s*' + DATE, 'i');
const INVOICE_NUMBER = /\binvoice\b\s*(?:#|no\.?|number|id)?\s*[:#]?\s*([A-Z0-9][A-Z0-9-]*\d[A-Z0-9-]*)/i;
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };

const pad = (n) => String(n).padStart(2, '0');

function formatMoney(raw) {
  const n = parseFloat(String(raw).replace(/,/g, ''));
  if (isNaN(n)) return '';
  return '$' + n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function toIsoDate(raw) {
  let m = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${pad(m[1])}-${pad(m[2])}`;
  m = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return raw;
  m = raw.match(/^([A-Za-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4})$/);
  if (m) {
    const month = MONTHS[m[1].slice(0, 3).toLowerCase()];
    if (month) return `${m[3]}-${pad(month)}-${pad(m[2])}`;
  }
  return '';
}

function receivedDate(iso) {
  if (!iso) return '';
  try {
    if (typeof DateTime !== 'undefined') return DateTime.fromISO(String(iso)).toFormat('yyyy-MM-dd');
  } catch (e) { /* fall through */ }
  return String(iso).slice(0, 10);
}

function findAmount(text) {
  for (const label of AMOUNT_LABELS) {
    const re = new RegExp('\\b' + label.replace(/ /g, '\\s+') + '\\b[^\\n$]{0,80}?' + MONEY, 'i');
    const m = text.match(re);
    if (m) return formatMoney(m[1]);
  }
  const before = text.match(new RegExp(MONEY + '\\s+total\\b', 'i'));
  if (before) return formatMoney(before[1]);
  const first = text.match(new RegExp(MONEY));
  return first ? formatMoney(first[1]) : '';
}

function findVendor(email, body) {
  // A forwarded invoice: use the original sender from the forwarded message.
  const fwd = body.match(/forwarded message[\s\S]*?\bFrom:\s*"?([^<"\n]+?)"?\s*</i);
  if (fwd) return fwd[1].trim();
  const sender = (email.from && email.from.value && email.from.value[0]) || {};
  if (sender.name && sender.name.trim()) return sender.name.replace(/"/g, '').trim();
  if (sender.address && sender.address.includes('@')) return sender.address.split('@')[1];
  return '';
}

function findCampus(text) {
  if (NETWORK.test(text)) return { campus: 'Network', note: '' };
  const named = CAMPUSES.filter((c) => c.pattern.test(text)).map((c) => c.name);
  // All three campuses named (e.g. one charge per campus) means the bill covers the whole network.
  if (named.length === CAMPUSES.length) return { campus: 'Network', note: '' };
  if (named.length === 1) return { campus: named[0], note: '' };
  if (named.length === 0) return { campus: '', note: 'Campus not stated.' };
  const list = named.length === 2
    ? named.join(' and ')
    : named.slice(0, -1).join(', ') + ' and ' + named[named.length - 1];
  return { campus: '', note: `Campus unclear: ${list} named.` };
}

// Look in the email first; use the PDF only if the email doesn't say.
function emailThenPdf(find, emailText, pdfText) {
  const fromEmail = find(emailText);
  if (fromEmail || !pdfText) return fromEmail;
  return find(pdfText);
}

function findInvoiceNumber(text) {
  const m = text.match(INVOICE_NUMBER);
  return m ? m[1] : '';
}

function findDueDate(text) {
  const m = text.match(DUE_DATE);
  return m ? toIsoDate(m[1]) : '';
}

function bodyText(email) {
  if (email.text) return String(email.text);
  if (email.html) return String(email.html).replace(/<[^>]+>/g, ' ');
  return '';
}

function categorise(all, body) {
  if (SUSPICIOUS.test(all)) return 'Possible fraud';
  if (REIMBURSEMENT.test(all)) return 'Reimbursement request';
  if (STATEMENT_CREDIT.test(all)) return 'Statement or credit';
  if (RECEIPT.test(all)) return 'Receipt or payment confirmation';
  if (MARKETING.test(all)) return 'Newsletter or marketing';
  if (INVOICE_WORDS.test(all)) return 'Invoice';
  if (SCHOOL_SIGNOFF.test(body.trim().slice(-200))) return 'Staff request';
  return 'Other';
}

// Matching: same invoice number (ignoring case, spaces, a leading #) and same first word of vendor.
function matchKey(invoiceNumber, vendor) {
  const inv = String(invoiceNumber ?? '').toUpperCase().replace(/\s+/g, '').replace(/^#/, '');
  if (!inv) return '';
  const first = String(vendor ?? '').trim().split(/\s+/)[0].toLowerCase().replace(/[^a-z0-9]/g, '');
  return inv + '|' + first;
}

function cell(row, name) {
  const v = row[name];
  return v === undefined || v === null ? '' : String(v).trim();
}

function toNumber(value) {
  const n = parseFloat(String(value ?? '').replace(/[$,\s]/g, ''));
  return isNaN(n) ? null : n;
}

// A due date from the sheet: 2026-10-22, 10/22/2026, October 22, 2026, or a Sheets date number.
function sheetDate(value) {
  if (value === undefined || value === null || value === '') return '';
  if (typeof value === 'number') {
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }).plus({ days: Math.floor(value) }).toFormat('yyyy-MM-dd');
  }
  return toIsoDate(String(value).trim());
}

function dueFlag(dueIso, status) {
  if (!dueIso || DECIDED.includes(status)) return '';
  const days = Math.round(DateTime.fromISO(dueIso, { zone: 'America/New_York' }).startOf('day').diff(TODAY, 'days').days);
  if (days < 0) return `Overdue by ${-days} day${days === -1 ? '' : 's'}`;
  if (days === 0) return 'Due today';
  if (days <= 7) return `Due in ${days} day${days === 1 ? '' : 's'}`;
  return '';
}

function missingFlag(bill, status) {
  if (status !== '' && status !== 'new') return '';
  const blanks = [];
  if (!bill.vendor) blanks.push('vendor');
  if (!bill.invoiceNumber) blanks.push('invoice #');
  if (!bill.amount) blanks.push('amount');
  if (!bill.dueDate) blanks.push('due date');
  if (!bill.campus) blanks.push('campus');
  return blanks.length ? 'Missing: ' + blanks.join(', ') : '';
}

function reviewText(bill) {
  const status = bill.status.toLowerCase();
  const parts = STICKY_FLAGS.filter((f) => bill.sticky.has(f));
  const due = dueFlag(bill.dueDate, status);
  if (due) parts.push(due);
  const missing = missingFlag(bill, status);
  if (missing) parts.push(missing);
  return parts.join('; ');
}

// ---------- Read the inputs ----------
const pdfByEmail = {};
$('Read PDFs').all().forEach((p, i) => {
  const src = p.pairedItem && typeof p.pairedItem.item === 'number' ? p.pairedItem.item : i;
  pdfByEmail[src] = typeof p.json.text === 'string' ? p.json.text : '';
});

// Bills already on the sheet (rows Marcus typed included).
const bills = [];
const billsByKey = {};
$('Get Bill Rows').all().forEach((item) => {
  const r = item.json;
  if (!r.row_number) return; // empty sheet
  const existingReview = cell(r, 'Review');
  const bill = {
    rowNumber: r.row_number,
    isNew: false,
    vendor: cell(r, 'Vendor'),
    invoiceNumber: cell(r, 'Invoice #'),
    amount: cell(r, 'Amount'),
    dueDate: sheetDate(r['Due date']),
    campus: cell(r, 'Campus'),
    status: cell(r, 'Status'),
    oldReview: existingReview,
    oldUpdates: cell(r, 'Updates'),
    updates: [],
    sticky: new Set(existingReview.split(';').map((s) => s.trim()).filter((s) => STICKY_FLAGS.includes(s))),
  };
  bills.push(bill);
  const key = matchKey(bill.invoiceNumber, bill.vendor);
  if (key && !billsByKey[key]) billsByKey[key] = bill;
});

// Emails, oldest first (skip the empty item a run with no new emails produces).
const emails = [];
$('Get Test Emails').all().forEach((item, i) => {
  if (item.json && item.json.id) emails.push({ email: item.json, pdfText: pdfByEmail[i] || '' });
});
emails.sort((a, b) => String(a.email.date || '').localeCompare(String(b.email.date || '')));

// ---------- Sort each email ----------
const logItems = [];
for (const { email, pdfText } of emails) {
  const subject = email.subject || '';
  const body = bodyText(email);
  const emailText = subject + '\n' + body;
  const all = emailText + '\n' + pdfText;
  const category = categorise(all, body);
  const received = receivedDate(email.date);
  const link = 'https://mail.google.com/mail/u/0/#all/' + email.id;
  const sender = (email.from && email.from.value && email.from.value[0]) || {};
  let result = 'Logged only';

  if (BILL_CATEGORIES.includes(category)) {
    const suspicious = category === 'Possible fraud';
    const vendor = findVendor(email, body);
    const invoiceNumber = emailThenPdf(findInvoiceNumber, emailText, pdfText);
    const amount = emailThenPdf(findAmount, emailText, pdfText);
    const dueDate = emailThenPdf(findDueDate, emailText, pdfText);
    const key = matchKey(invoiceNumber, vendor);
    const match = key ? billsByKey[key] : null;

    if (match) {
      // A resend, reminder, forward or fraud email for a bill already there: note it, don't change the row.
      let line = `${received}: ${suspicious ? 'possible fraud email' : 'follow-up email'} '${subject}'.`;
      const rowAmount = toNumber(match.amount);
      const emailAmount = toNumber(amount);
      if (emailAmount !== null && rowAmount !== null && Math.abs(emailAmount - rowAmount) > 0.005) line += ` Amount in this email: ${amount}.`;
      if (dueDate && match.dueDate && dueDate !== match.dueDate) line += ` Due date in this email: ${dueDate}.`;
      match.updates.push(line);
      if (suspicious) match.sticky.add('Possible fraud');
      if (!match.isNew && APPROVED.includes(match.status.toLowerCase())) match.sticky.add('Changed after approval');
      result = 'Added to existing bill';
    } else {
      let campusResult = findCampus(emailText);
      if (!campusResult.campus && campusResult.note === 'Campus not stated.' && pdfText) campusResult = findCampus(pdfText);
      const { campus, note: campusNote } = campusResult;
      const notes = [];
      if (suspicious) notes.push('Needs review: possible fraud.');
      if (!vendor) notes.push('Vendor not stated.');
      if (!invoiceNumber) notes.push('Invoice # not stated.');
      if (!amount) notes.push('Amount not stated.');
      if (!dueDate) notes.push('Due date not stated.');
      if (campusNote) notes.push(campusNote);
      const bill = {
        isNew: true, received, vendor, invoiceNumber, amount, dueDate, campus, status: 'New',
        notes: notes.join(' '), link, updates: [], sticky: new Set(suspicious ? ['Possible fraud'] : []),
      };
      bills.push(bill);
      if (key) billsByKey[key] = bill;
      result = 'New bill row';
    }
  }

  logItems.push({
    json: {
      kind: 'log',
      'Date received': received,
      'From': (sender.name || sender.address || '').replace(/"/g, '').trim(),
      'Subject': subject,
      'Category': category,
      'Result': result,
      'Email link': link,
      emailId: email.id,
    },
    pairedItem: { item: 0 },
  });
}

// ---------- Build the output ----------
const results = [];
for (const bill of bills) {
  const review = reviewText(bill);
  if (bill.isNew) {
    results.push({
      json: {
        kind: 'add',
        'Date received': bill.received,
        'Vendor': bill.vendor,
        'Invoice #': bill.invoiceNumber,
        'Amount': bill.amount,
        'Due date': bill.dueDate,
        'Campus': bill.campus,
        'Status': 'New',
        'Paid date': '',
        'Notes': bill.notes,
        'Review': review,
        'Updates': bill.updates.join('\n'),
        'Email link': bill.link,
      },
      pairedItem: { item: 0 },
    });
  } else {
    const updates = [bill.oldUpdates, ...bill.updates].filter(Boolean).join('\n');
    if (review !== bill.oldReview || updates !== bill.oldUpdates) {
      results.push({
        json: { kind: 'update', row_number: bill.rowNumber, 'Vendor': bill.vendor, 'Invoice #': bill.invoiceNumber, 'Review': review, 'Updates': updates },
        pairedItem: { item: 0 },
      });
    }
  }
}

return results.concat(logItems);
